// PedidoServiceServer is the server API for PedidoService service.
// All implementations must embed UnimplementedPedidoServiceServer
// for forward compatibility.
//
// services
type PedidoServiceServer interface {
	Create(context.Context, *CreatePedidoRequest) (*CreatePedidoResponse, error)
	CreateValidated(context.Context, *CreatePedidoRequest) (*CreatePedidoResponse, error)
	Update(context.Context, *UpdatePedidoRequest) (*UpdatePedidoResponse, error)
	SetAcompanhamento(context.Context, *SetAcompanhamentoRequest) (*SetAcompanhamentoResponse, error)
	// Reordena os itens do documento: os ids vêm na ordem final e precisam ser exatamente
	// os itens atuais. A nota fiscal sai na ordem do documento.
	ReorderItems(context.Context, *ReorderItemsRequest) (*ReorderItemsResponse, error)
	Delete(context.Context, *DeletePedidoRequest) (*DeletePedidoResponse, error)
	Get(context.Context, *GetPedidoRequest) (*GetPedidoResponse, error)
	List(context.Context, *ListPedidoRequest) (*ListPedidoResponse, error)
	Report(context.Context, *ReportRequest) (*ReportResponse, error)
	Print(context.Context, *PrintPedidoRequest) (*PrintPedidoResponse, error)
	GenerateFromOrcamento(context.Context, *GenerateFromOrcamentoRequest) (*GenerateFromOrcamentoResponse, error)
	Cancel(context.Context, *CancelPedidoRequest) (*CancelPedidoResponse, error)
	Clone(context.Context, *ClonePedidoRequest) (*ClonePedidoResponse, error)
	AddProduct(context.Context, *AddProductRequest) (*AddProductResponse, error)
	UpdateProduct(context.Context, *UpdateProductRequest) (*UpdateProductResponse, error)
	DeleteProduct(context.Context, *DeleteProductRequest) (*DeleteProductResponse, error)
	AddService(context.Context, *AddServiceRequest) (*AddServiceResponse, error)
	UpdateService(context.Context, *UpdateServiceRequest) (*UpdateServiceResponse, error)
	DeleteService(context.Context, *DeleteServiceRequest) (*DeleteServiceResponse, error)
	AddPayment(context.Context, *AddPaymentRequest) (*AddPaymentResponse, error)
	DeletePayment(context.Context, *DeletePaymentRequest) (*DeletePaymentResponse, error)
	CancelPayment(context.Context, *CancelPaymentRequest) (*CancelPaymentResponse, error)
	// Efetiva pagamentos com status LANCADO, realizando lancamentos financeiros e fechando o pedido
	EffectuatePayments(context.Context, *EffectuatePaymentsRequest) (*EffectuatePaymentsResponse, error)
	SendByEmail(context.Context, *SendByEmailRequest) (*SendByEmailResponse, error)
	// Retorna o PDF do pedido em base64 para a página pública de download (acesso via token)
	DownloadPdfPublico(context.Context, *DownloadPdfPublicoRequest) (*DownloadPdfPublicoResponse, error)
	AplicaTabelaPreco(context.Context, *AplicaTabelaPrecoRequest) (*AplicaTabelaPrecoResponse, error)
	DfeDanfe(context.Context, *DfeDanfeRequest) (*DfeDanfeResponse, error)
	Import(context.Context, *ImportRequest) (*ImportResponse, error)
	// Cria pedidos mesclados com base nas IDs recebidas
	MesclaPedidos(context.Context, *MesclaPedidosRequest) (*MesclaPedidosResponse, error)
	// Vincula um novo pedido à mesclagem já criada
	AddPedidoVinculado(context.Context, *AddPedidoVinculadoRequest) (*AddPedidoVinculadoResponse, error)
	// Delete um dos pedidos da mesclagem
	DeletePedidoVinculado(context.Context, *DeletePedidoVinculadoRequest) (*DeletePedidoVinculadoResponse, error)
	// Envia uma nota fiscal de acordo com as configurações de integração
	EnviaNFe(context.Context, *EnviaNFeRequest) (*EnviaNFeResponse, error)
	// Sincroniza o pedido com o estado atual da NF vinculada
	SincronizaNFe(context.Context, *SincronizaNFeRequest) (*SincronizaNFeResponse, error)
	// Sincroniza os dados desnormalizados da pessoa (e vinculos) a partir do cadastro.
	// Persiste via DAO para permitir atualizacao mesmo com pedido FECHADO/CANCELADO.
	SincronizaPessoa(context.Context, *SincronizaPessoaRequest) (*SincronizaPessoaResponse, error)
	// Permite vincular uma NF ao pedido manualmente
	VinculaNFManual(context.Context, *VinculoNfManualRequest) (*VinculoNfManualResponse, error)
	SendPaymentLink(context.Context, *SendPaymentLinkRequest) (*SendPaymentLinkResponse, error)
	CorrecaoMovimentacao(context.Context, *CorrecaoMovimentacaoRequest) (*CorrecaoMovimentacaoResponse, error)
	ConfirmOrderReceipt(context.Context, *ConfirmOrderReceiptRequest) (*ConfirmOrderReceiptResponse, error)
	// Adiciona múltiplos arquivos ao pedido, delegando criação ao FileManager
	AddFiles(context.Context, *AddFilesRequest) (*AddFilesResponse, error)
	// Remove arquivos do pedido e do FileManager
	RemoveFiles(context.Context, *RemoveFilesRequest) (*RemoveFilesResponse, error)
	// Aprova ou recusa um arquivo do pedido que está aguardando moderação
	SetFileApproval(context.Context, *SetFileApprovalRequest) (*SetFileApprovalResponse, error)
	Export(context.Context, *ExportOrdersRequest) (*ExportOrdersResponse, error)
	// Envia email solicitando avaliacao dos produtos do pedido
	SendReviewEmail(context.Context, *SendReviewEmailRequest) (*SendReviewEmailResponse, error)
	// Recalcula a comissao de todos os itens do pedido com base no percentual atual do vendedor/tecnico
	RecalcularComissao(context.Context, *RecalcularComissaoRequest) (*RecalcularComissaoResponse, error)
	// Renumera todos os documentos do tipo em ordem de criação, a partir do número
	// informado; o próximo documento criado continua depois do último. Recusado quando
	// algum documento do tipo tem pagamento, nota fiscal ou já foi fechado.
	Renumber(context.Context, *RenumberRequest) (*RenumberResponse, error)
	// Agrupa os itens ainda não enviados por impressora de produção e devolve os
	// jobs de impressão (cozinha/bar), marcando os itens como enviados.
	EnviarProducao(context.Context, *EnviarProducaoRequest) (*EnviarProducaoResponse, error)
	// Grava a confirmação de impressão (ou erro) de cada item após o transporte
	// (Linker/plugin) retornar.
	ConfirmarImpressaoProducao(context.Context, *ConfirmarImpressaoProducaoRequest) (*ConfirmarImpressaoProducaoResponse, error)
	// Marca itens como entregues (com data/hora) para cálculo do tempo de preparo.
	MarcarItemEntregue(context.Context, *MarcarItemEntregueRequest) (*MarcarItemEntregueResponse, error)
	// Produtos para inserção rápida no PDV: mais vendidos e últimos lançados.
	GetQuickProdutos(context.Context, *GetQuickProdutosRequest) (*GetQuickProdutosResponse, error)
	// Soma o que cada vendedor realizou no período, para quem acompanha meta. A base diz o que
	// conta: o valor do documento na data dele, ou o valor pago em cada pagamento, na data do
	// pagamento — nesse caso um documento parcialmente pago entra pelo que já foi pago.
	ResumoVendasPorVendedor(context.Context, *ResumoVendasPorVendedorRequest) (*ResumoVendasPorVendedorResponse, error)
	mustEmbedUnimplementedPedidoServiceServer()
}

